insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 4, 'E Pedro, olhando fixamente para ele, junto com João, disse: Olha para nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 5, 'E [o aleijado] ficou prestando atenção neles, esperando receber deles alguma coisa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 6, 'E Pedro disse: Prata e ouro eu não tenho; mas o que eu tenho, isso eu te dou: no nome de Jesus Cristo, o nazareno, levanta-te, e anda!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 7, 'E, tomando-o pela mão direita, levantou [-o] ; e logo os seus pés e tornozelos ficaram firmes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 8, 'E ele, saltando, pôs-se de pé, e andou, e entrou com eles no Templo, andando, e saltando, e louvando a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 9, 'E todo o povo o viu andar, e louvar a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 10, 'E eles o reconheceram, que este era o que se sentava [para pedir] esmola perto da porta formosa do Templo; e ficaram cheios de surpresa e espanto, por causa do que tinha lhe acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 11, 'E o aleijado que tinha sido curado, tendo se apegado a Pedro e a João, todo o povo correu maravilhado a eles ao pórtico, que se chama de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 12, 'Quando Pedro viu [isso] , respondeu ao povo: “Homens israelitas, por que vos maravilhais disto? Ou por que vós olhais tão atentamente para nós, como se por nosso próprio poder ou devoção divina o tivéssemos feito andar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 13, 'O Deus de Abraão, e de Isaque, e de Jacó, o Deus de nossos pais, glorificou a seu filho Jesus, ao qual vós entregastes, e diante do rosto de Pilatos o negastes, [mesmo] ele julgando que fosse solto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 14, 'Mas vós negastes ao santo e justo, e pedistes que um homem assassino fosse vos dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 15, 'E vós matastes ao Príncipe da vida, ao qual Deus ressuscitou dos mortos, do que nós somos testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 16, 'E pela fé em seu nome, o nome dele deu firmeza a este, que vedes e conheceis; e a fé que é por meio dele deu a este perfeita saúde na presença de todos vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 17, 'E agora, irmãos, eu sei que vós fizestes [isso] por ignorância, assim como também vossos líderes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 18, 'Mas Deus cumpriu assim o que já antes pela boca de todos os seus profetas ele tinha anunciado, que o Cristo tinha de sofrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 19, 'Arrependei-vos, pois, e convertei-vos, para que vosso pecados sejam apagados, quando vierem os tempos do refrigério da presença do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 20, 'E ele enviar a Jesus Cristo, que já vos foi pregado anteriormente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 21, 'Ao qual convém que o céu receba até os tempos da restauração de todas as coisas, que Deus falou pela boca de todos os seus santos profetas, desde o princípio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 22, 'Porque Moisés disse aos [nossos] pais: O Senhor, vosso Deus, levantará dentre vossos irmãos um profeta como eu; a ele ouvireis em tudo o que ele vos falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 23, 'E será que toda pessoa que não ouvir este profeta será exterminada do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 24, 'E também todos os profetas, desde Samuel e os posteriores, todos os que falaram, também anunciaram com antecedência destes dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 25, 'Vós sois os filhos dos profetas e do pacto que Deus estabeleceu com nossos pais, dizendo a Abraão: E em tua semente serão abençoadas todas as famílias da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 3, 26, 'Deus, ao ressuscitar seu filho Jesus, primeiro o enviou a vós, para que [nisto] vos abençoasse: afastando cada um de vós de vossas maldades”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 1, 'E enquanto eles ainda estavam falando ao povo, vieram sobre eles os sacerdotes, e o oficial do Templo, e os saduceus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 2, 'Muito incomodados por eles ensinarem ao povo, e anunciarem no [nome] de Jesus a ressurreição dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 3, 'E puseram as mãos sobre eles, e os puseram na prisão até o dia seguinte, porque já era tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 4, 'E muitos dos que ouviram a palavra, creram; e era o número dos homens de cerca de cinco mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 5, 'E aconteceu no dia seguinte, que os chefes, e anciãos, e escribas, se reuniram em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 6, 'E Anás, o sumo sacerdote, e Caifás, e João, e Alexandre, e todos quantos havia da linhagem do governo sacerdotal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 7, 'E pondo-os no meio, perguntaram [-lhes] : Por meio de que poder ou por qual nome vós fizestes isto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 8, 'Então Pedro, cheio do Espírito Santo, lhes disse: Chefes do povo, e anciões de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 9, 'Se hoje somos interrogados quanto a uma boa ação [feita] a um enfermo, pela qual este foi curado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 10, 'Seja conhecido a todos vós, e a todos o povo de Israel, que pelo nome de Jesus Cristo, o nazareno, aquele que vós crucificastes, ao qual Deus ressuscitou dos mortos, por ele este [homem] está são diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 11, 'Este é a pedra que foi desprezada por vós, edificadores; a qual foi feita por cabeça de esquina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 12, 'E em nenhum outro há salvação; porque nenhum outro nome há abaixo do céu, dado entre os seres humanos, em quem devemos ser salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 13, 'E eles, ao verem a ousadia de Pedro, e de João; e informados que eles eram homens sem instrução e ordinários, maravilharam-se; e eles sabiam que eles tinham estado com Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 14, 'E vendo estar com eles o homem que tinha sido curado, nada tinham a dizer contra [eles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 15, 'E mandando-os saírem do supremo conselho, discutiam entre si,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 16, 'Dizendo: O que faremos a estes homens? Porque um sinal notório foi feito por eles, manifesto a todos os que habitam em Jerusalém, e não podemos negar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 17, 'Mas para que [esta notícia] não seja ainda mais divulgada entre o povo, façamos sérias ameaças a eles, para que nunca mais falem a ninguém neste nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 18, 'E chamando-os, ordenaram-lhes que nunca mais falassem nem ensinassem no nome de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 19, 'Mas, respondendo Pedro, e João, disseram-lhes: Julgai se é justo diante de Deus, ouvir a vós mais do que a Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 20, 'Porque nós não podemos deixar de falar daquilo que temos visto e ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 21, 'Mas eles, tendo os ameaçado ainda mais, nada acharam [de motivo] para os castigar, e os deixaram ir por causa do povo; porque todos glorificavam a Deus pelo que tinha acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 22, 'Porque era de mais de quarenta anos o homem em quem este milagre de cura tinha sido feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 23, 'E eles, tendo sido soltos, vieram aos seus [companheiros] , e lhes contaram tudo o que os chefes dos sacerdotes e os anciãos tinham lhes dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 24, 'E eles, ao ouvirem [isto] , levantaram concordantes a voz a Deus, e disseram: Senhor, tu és o Deus que fizeste o céu, a terra, o mar, e todas as coisas que neles há;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 25, 'Que pela boca de teu servo Davi disseste: Por que os gentios se irritam, e os povos gastam seus pensamentos em coisas vãs?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 26, 'Os reis da terra se levantaram, e os príncipes se juntaram em um mesmo [propósito] contra o Senhor, e contra o seu Ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 27, 'Porque verdadeiramente contra teu Santo Filho Jesus, ao qual tu ungiste, se ajuntaram, tanto Herodes, como Pôncio Pilatos, com os gentios e os povos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 28, 'Para fazerem tudo o que a tua mão e o teu conselho desde antes tinha determinado para acontecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 29, 'E agora, Senhor, observa as ameaças deles, e dá a teus servos, que com toda ousadia falem tua palavra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 30, 'Estendendo tua mão para a cura, e que se façam sinais e milagres pelo nome de teu Santo filho Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 31, 'E tendo orado, agitou-se o lugar em que eles estavam juntos, e foram todos cheios do Espírito Santo, e falavam a palavra de Deus com ousadia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 32, 'E a multidão dos que criam, era de um só oração e uma só alma; e ninguém dizia ser próprio coisa alguma de seus bens, mas todas as coisas lhes eram comuns.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 33, 'E com grande poder os apóstolos davam testemunho da ressurreição do Senhor Jesus; e em todos eles havia grande graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 34, 'Porque também nenhum necessitado havia entre eles; porque todos os que possuíam propriedades de terras, ou casas, vendendo [-as] , traziam o valor das coisas vendidas, e [o] depositavam junto aos pés dos apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 35, 'E a cada um se repartia segundo cada qual tinha necessidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 36, 'E José, chamado pelos apóstolos pelo sobrenome de Barnabé (que traduzido é filho da consolação), levita, natural do Chipre,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 4, 37, 'Tendo ele uma propriedade de terra, vendeu [-a] , e trouxe o valor, e [o] depositou junto aos pés dos apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 1, 'E um certo homem, de nome Ananias, com Safira, sua mulher, vendeu uma propriedade de terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 2, 'E escondeu [parte] do valor, sabendo também a mulher dele; e trazendo uma certa parte, depositou [-a] junto aos pés dos apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 3, 'E Pedro disse: Ananias, por que Satanás encheu teu coração, para que mentisses ao Espírito Santo, e escondesses [parte] do valor da propriedade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 4, '[Se] mantivesses [tua propriedade] , ela não seria mantida contigo? E, tendo sido vendida, [o dinheiro da venda] não estava em teu poder? Por que decidiste [isto] em teu coração? Não mentiste aos seres humanos, mas sim a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 5, 'E Ananias, ao ouvir estas palavras, caiu e deixou de respirar. E veio um grande temor sobre todos os que ouviram isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 6, 'E os rapazes, tendo se levantado, levaram-no fora, e [o] sepultaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 7, 'E passando o intervalo de cerca de três horas, entrou também sua mulher, não sabendo o que tinha acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 8, 'E Pedro disse a ela: Dize-me, vendestes por [aquele] tanto aquela propriedade?E ela disse: Sim, por [aquele] tanto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 9, 'E Pedro lhe disse: Por que vós fizestes acordo para tentar ao Espírito do Senhor? Eis que [estão] à porta os pés daqueles que sepultaram a teu marido, e eles também [te] levarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 10, 'E imediatamente ela caiu junto aos pés deles, e deixou de respirar. E os rapazes, ao entrarem, encontraram-na morta; e levando- [a] fora, sepultaram-na junto ao marido dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 11, 'E veio um grande temor em toda a igreja, e em todos que ouviram estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 12, 'E pelas mãos dos apóstolos foram feitos muitos sinais e milagres entre o povo. E estavam todos em concordância no pórtico de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 13, 'Mas dos outros, ninguém ousava se juntar a eles; porém o povo os estimava grandemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 14, 'E cada vez mais os que criam no Senhor se aumentavam, multidões tanto de homens como de mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 15, 'De maneira que traziam os enfermos às ruas, e os botavam em camas e macas, para que, vindo Pedro, pelo menos a sombra dele cobrisse a alguns deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 16, 'E também das cidades vizinhas vinha uma multidão a Jerusalém, trazendo enfermos, e atormentados por espíritos imundos, os quais todos eram curados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 17, 'E levantando-se o sumo sacerdote, e todos os que estavam com ele (que eram do grupo sectário dos saduceus), eles se encheram de inveja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 18, 'E puseram suas mãos nos apóstolos, e os colocaram na prisão pública.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 19, 'Mas um anjo do Senhor, durante a noite, abriu as portas da prisão; e levando-os para fora, disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 20, 'Ide; ficai em pé, e falai no Templo ao povo todas as palavras desta vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 21, 'E eles, ouvindo [isto] , entraram de manhã cedo no templo, e ensinavam. Mas vindo o sumo sacerdote, e os que estavam com ele, chamaram ao supremo conselho, e a todos os anciãos dos filhos de Israel, e mandaram à prisão, para que os trouxessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 22, 'Mas quando os oficiais vieram, não os acharam na prisão; e voltando, anunciaram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 23, 'Dizendo: Nós achamos a prisão fechada, em toda segurança, e com os guardas que estavam fora junto às portas; mas quando [as] abrimos, a ninguém achamos dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 24, 'Quando o [sumo] sacerdote, o chefe da guarda do Templo, e os chefes dos sacerdotes ouviram estas palavras, eles duvidaram deles quanto o que aquilo viria a ser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 25, 'E vindo alguém, anunciou-lhes, dizendo: Eis que os homens que vós pusestes na prisão estão no Templo, e ensinam ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 26, 'Então foi o chefe da guarda do Templo com os oficiais, e os trouxe, [mas] não com violência, porque temiam ao povo, para que não fossem apedrejados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 27, 'E quando os trouxeram, apresentaram-nos ao supremo conselho. E o sumo sacerdote perguntou a eles, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 28, 'Não vos ordenamos expressamente para não ensinardes [mais] neste nome? E eis que vós enchestes a Jerusalém com vossa doutrina, e quereis trazer sobre nós o sangue deste homem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 29, 'E Pedro, respondendo com os apóstolos, disseram: Maior obrigação é obedecer a Deus do que às pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 30, 'O Deus de nossos Pais ressuscitou a Jesus, ao qual vós matastes, pendurando [-o] no madeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 31, 'A este Deus exaltou com sua [mão] direita [por] Príncipe e Salvador, para dar a Israel arrependimento e perdão de pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 32, 'E nós somos testemunhas dele quanto a estas palavras, e também o Espírito Santo, o qual Deus tem dado a aqueles que lhe obedecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 33, 'E eles, ouvindo [isso] , enfureceram-se grandemente, e planejaram matá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 34, 'Mas, levantando-se no supremo conselho um certo fariseu, de nome Gamaliel, instrutor da Lei, bem honrado por todo o povo, ele mandou levarem aos apóstolos para fora por um pouco [de tempo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 35, 'E lhes disse: Homens israelitas, olhai por vós mesmos, quanto ao que haveis de fazer a estes homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 36, 'Porque antes destes dias se levantou Teudas, dizendo ser alguém; ao qual se ajuntaram cerca de quatrocentos homens; ao qual foi morto, e todos os que acreditavam [nele] foram dispersos, e reduzidos a nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 37, 'Depois deste se levantou Judas, o galileu, nos dias do censo; e perverteu muito do povo atrás dele; e este também pereceu, e todos os que acreditavam nele foram dispersos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 38, 'E agora, eu vos digo, afastai-vos destes homens, e deixai-os; porque se este conselho ou esta obra for humana, ela se desfará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 39, 'Mas se é de Deus, vós não a podereis desfazer; para que não venhais a ser achados de também lutardes contra Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 40, 'E concordaram com ele. E chamando aos apóstolos, tendo [os] açoitado, mandaram [-lhes] que não [mais] falassem no nome de Jesus; e os deixaram ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 41, 'Então eles saíram da presença do supremo conselho, alegres por terem sido considerados dignos de serem humilhados por causa do nome dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 5, 42, 'E todos os dias no Templo, e pelas casas, não paravam de ensinar e de anunciar a Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 1, 'Naqueles dias, ao se multiplicar [o número] de discípulos, houve uma murmuração dos gregos contra os hebreus, de que suas viúvas estavam sendo desprezadas no serviço diário [de entrega de comida] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 2, 'E os doze, chamando à multidão dos discípulos, disseram: Não é bom que nós deixemos a palavra de Deus para servirmos às mesas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 3, 'Portanto, irmãos, buscai sete homens dentre vós, de quem haja [bom] testemunho, cheios do Espírito Santo e de sabedoria, aos quais constituamos sobre esta importante tarefa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 4, 'Nós, porém, perseveraremos na oração e no serviço da palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 5, 'E esta palavra foi do agrado diante de toda a multidão, e escolheram a Estêvão, homem cheio de fé e do Espírito Santo, e Filipe, Prócoro, Nicanor, Timom, Parmenas e a Nicolão, o prosélito de Antioquia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 6, 'Aos quais se apresentaram diante dos apóstolos; e eles, orando, puseram as mãos sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 7, 'E a palavra de Deus crescia, e o número dos discípulos se multiplicava muito em Jerusalém; e grande multidão dos sacerdotes obedecia à fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 8, 'E Estêvão, cheio de fé e poder, fazia milagres e grandes sinais entre o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 9, 'E levantaram-se alguns da sinagoga, [que era] chamada [sinagoga] dos libertos, cireneus, e alexandrinos, e dos [que eram] da Cilícia, e da Ásia, e discutiam contra Estêvão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 10, 'E eles não podiam resistir à sabedoria e ao Espírito com que ele falava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 11, 'Então eles subornaram a uns homens, [para que] dissessem: Nós o ouvimos falando palavras blasfemas contra Moisés e [contra] Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 12, 'E incitaram ao povo, aos anciãos e aos escribas; e vieram sobre [Estêvão] , e o detiveram, e o levaram ao supremo conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 13, 'E apresentaram falsas testemunhas, que diziam: Este homem não para de falar palavras blasfemas contra este santo lugar, e [contra] a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 14, 'Porque nós o ouvimos dizer que este Jesus Nazareno vai destruir este lugar, e mudar os costumes que Moisés nos entregou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 6, 15, 'Então todos os que estavam sentados no supremo conselho, observando-o com atenção, viram o rosto dele como de um anjo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 1, 'E disse o chefe dos sacerdotes: Por acaso é isto assim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 2, 'E ele disse: Homens irmãos e pais, ouvi: o Deus da glória apareceu a nosso pai Abraão, estando ele na Mesopotâmia, antes de habitar em Harã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 3, 'E disse-lhe: Sai de tua terra, e de tua parentela, e vem a terra que eu te mostrarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 4, 'Então ele saiu da terra dos caldeus, [e] habitou em Harã. E dali, depois que morreu seu pai, ele partiu para esta terra, em que agora vós habitais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 5, 'E [Deus] não lhe deu herança nela, nem mesmo a pegada de um pé; mas prometeu que a daria a ele em propriedade, e a sua semente depois dele, não tendo ele filho [ainda] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 6, 'E Deus falou assim: Tua semente será peregrina em terra alheia, e a escravizarão, e a maltratarão [por] quatrocentos anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 7, 'E à nação a quem eles servirem, eu a julgarei, (disse Deus). E depois disso eles sairão, e me servirão neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 8, 'E ele lhe deu o pacto da circuncisão; e assim gerou a Isaque, e o circuncidou ao oitavo dia; e Isaque [gerou] a Jacó, e Jacó aos doze patriarcas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 9, 'E os patriarcas, tendo inveja [de] José, venderam [-no] ao Egito; mas Deus era com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 10, 'E o livrou de todas as suas aflições, e lhe deu graça e sabedoria diante de Faraó, rei do Egito; e o pôs [por] governador sobre o Egito, e toda a sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 11, 'E veio fome sobre toda a terra do Egito e de Canaã, e grande aflição; e nossos pais não achavam alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 12, 'Mas Jacó, ao ouvir que havia cereal no Egito, ele enviou nossos pais a primeira vez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 13, 'E na segunda [vez] ,José foi reconhecido pelos seus irmãos, e a família de José foi conhecia por Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 14, 'E José mandou chamar a seu pai Jacó, e toda a sua parentela, setenta e cinco almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 15, 'E Jacó desceu ao Egito, e morreu; ele, e nossos pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 16, 'E foram levados a Siquém, e postos na sepultura que Abraão, por uma quantia em dinheiro, tinha comprado dos filhos de Emor, [pai] de Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 17, 'Mas quando chegou perto o tempo da promessa que Deus tinha prometido a Abraão, o povo cresceu e se multiplicou no Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 18, 'Até que se levantou outro rei, que não tinha conhecido a José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 19, 'Este, usando de astúcia para com nossa parentela, maltratou a nossos pais, até fazendo com que eles rejeitassem suas crianças, para que não sobrevivessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 20, 'Naquele tempo nasceu Moisés, e ele era muito formoso para Deus, e ele foi criado por três meses na casa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 21, 'E tendo sido abandonado, a filha de Faraó o tomou, e o criou para si como filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 22, 'E Moisés foi instruído em toda a sabedoria dos egípcios; e era poderoso em palavras e ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 23, 'E quando lhe foi completado o tempo de quarenta anos [de idade] , veio ao seu coração [o desejo] de visitar a seus irmãos, os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 24, 'E vendo um [deles] sofrendo injustamente, defendeu [-o] , e vingou pelo que tinha sido oprimido, matando ao egípcio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 25, 'E ele pensava que seus irmãos tivessem entendido que Deus ia lhes dar liberdade por meio da mão dele; mas eles não entenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 26, 'E no dia seguinte, estando [uns deles] lutando, ele foi visto por eles, e ordenou-lhes [fazerem] as pazes, dizendo: Homens, vós sois irmãos, por que fazeis mal um ao outro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 27, 'Mas aquele que maltratava a seu próximo empurrou-o, dizendo: Quem te pôs por chefe e juiz sobre nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 28, 'Queres tu [também] matar a mim, assim como ontem mataste ao egípcio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 29, 'E com esta palavra Moisés fugiu, e foi peregrino na terra de Midiã, onde ele gerou dois filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 30, 'E completados quarenta anos, um anjo do Senhor lhe apareceu no deserto do monte Sinai, em uma sarça inflamada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 31, 'Moisés, ao ver [isso] ,maravilhou-se da visão; e ao aproximar-se para ver, veio até ele a voz do Senhor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 32, '[Dizendo] : Eu [sou] o Deus de teus pais, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó. E Moisés, estando tremendo, não ousava olhar com atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 33, 'E o Senhor lhe disse: Descalça-te as sandálias de teus pés, porque o lugar em que estás é terra santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 34, 'Eu tenho visto com atenção a aflição de meu povo que [está] no Egito, e ouvi o gemido deles, e eu desci para livrá-los; então vem agora, eu te enviarei ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 35, 'A este Moisés, ao qual tinham negado, dizendo: Quem te pôs por chefe e juiz, A este Deus enviou por chefe e libertador, pela mão do anjo que lhe apareceu na sarça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 36, 'Este os levou para fora, fazendo milagres e sinais na terra do Egito, e no mar Vermelho, e no deserto, [por] quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 37, 'Este é o Moisés que disse aos filhos de Israel: O Senhor, vosso Deus, vos levantará um profeta dentre vossos irmãos, como a mim; a ele ouvireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 38, 'Este é aquele que esteve na congregação [do povo] no deserto com o anjo que tinha lhe falado no monte Sinai, e [com] nossos pais; o qual recebeu as palavras vivas, para dar a nós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 39, 'Ao qual nossos pais não quiseram obedecer; mas [o] rejeitaram, e seus corações voltaram ao Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 40, 'Ao dizerem a Arão: Faz-nos deuses, que irão adiante de nós; porque [quanto a] este Moisés, que nos levou para fora da terra do Egito, nós não sabemos o que aconteceu com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 41, 'E naqueles dias eles fizeram o bezerro, o ofereceram sacrifício ao ídolo, e se alegraram nas obras de suas [próprias] mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 42, 'E Deus se afastou[deles] , e os entregou, para que servissem ao exército do céu, como está escrito no livro dos profetas: Ó casa de Israel, acaso foi a mim que oferecestes animais sacrificados, e ofertas no deserto por quarenta anos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 43, 'Porém tomastes [para si] a tenda de Moloque, e a estrela de vosso Deus Renfã, figuras que vós fizeste para adorá-las; e eu [por isso] vos expulsarei para além da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 44, 'No deserto estava entre nossos pais o Tabernáculo do testemunho, assim como ele tinha ordenado, falando a Moisés, que o fizesse segundo o modelo que tinha visto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 45, 'O qual, recebendo [-o] também nossos Pais, eles levaram com Josué para a possessão dos gentios que Deus expulsou diante de nossos Pais, até os dias de Davi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 46, 'O qual foi do agrado diante de Deus, e pediu para achar um tabernáculo para o Deus de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 47, 'E Salomão lhe construiu uma casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 48, 'Mas o Altíssimo não habita em templos feitos por mãos, assim como o profeta diz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 49, 'O céu é o meu trono, e a terra [é] o estrado dos meus pés; que casa vós construireis para mim?, diz o Senhor; ou Qual é o lugar do meu repouso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 50, 'Por acaso não [foi] minhão mão [que] fez todas estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 51, 'Vós, obstinados e incircuncisos de coração e de ouvidos! Vós sempre resistis ao Espírito Santo! Tal como vossos pais [foram] , assim também [sois] vós!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 52, 'Qual dos profetas vossos pais não perseguiram? E eles mataram a todos os que anunciaram com antecedência a vinda do Justo, do qual agora vós tendes sido traidores e homicidas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 53, 'Que recebestes a Lei por ordem de anjos, e não [a] guardastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 54, 'Eles, ao ouvirem estas coisas, retalharam-se de raiva em seus corações, e rangiam os dentes contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 55, 'Mas ele, estando cheio do Espírito Santo, olhando firmemente para o céu, viu à glória de Deus, e a Jesus, que estava à direita de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 56, 'E disse: Eis que vejo os céus abertos, e o Filho do homem, que está a direita de Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 57, 'Mas eles, clamando com alta voz, taparam seus próprios ouvidos, e correram juntos contra ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 58, 'E, lançando [-o] fora da cidade, [o] apedrejaram; e as testemunhas puseram as roupas deles junto aos pés de um rapaz chamado Saulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 59, 'E apedrejaram a Estêvão, que estava clamando e dizendo: Senhor Jesus, recebe o meu espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 7, 60, 'E pondo-se de joelhos, clamou com alta voz: Senhor, não os culpes por este pecado.E tendo dito isto, morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 1, 'E Saulo também consentia na morte dele. E naquele dia foi feita uma grande perseguição contra a igreja que estava em Jerusalém; e todos foram dispersos pelas regiões da Judeia, e de Samaria, exceto os apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 2, 'E [alguns] homens devotos levaram juntos a Estêvão [para enterrá-lo] ,e fizeram grande pranto por causa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 3, 'E Saulo tentava destruir a igreja, entrando nas casas, e puxando a homens e mulheres, entregava-os à prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 4, 'Os que, pois, estavam dispersos, passavam anunciando a palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 5, 'E Filipe, tendo descido à cidade de Samaria, pregava-lhes a Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 6, 'E as multidões prestavam atenção em concordância às coisas que eram ditas por Filipe, ao ouvirem e verem os sinais que ele fazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 7, 'Porque os espíritos imundos, clamando em alta voz, saíam de muitos que os tinham; e muitos paralíticos e aleijados foram curados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 8, 'E havia grande alegria naquela cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 9, 'E havia um certo homem, de nome Simão, que antes naquela cidade usava de magia, e fazia o povo de Samaria ficar admirado, dizendo de si mesmo ser alguém grande;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 10, 'A quem eles todos davam atenção, desde o menor até o maior, diziam: Este é o grande poder de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 11, 'E davam atenção a ele, porque com suas magias ele há muito tempo tinha lhes causado admiração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 12, 'Mas quando creram em Filipe, que lhes anunciava o Evangelho do Reino de Deus, e o nome de Jesus Cristo, eles foram batizados, tanto homens como mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 13, 'E até mesmo Simão creu; e tendo sido batizado, ele continuou com Filipe; e vendo os sinais e maravilhas que eram feitas, ele ficou admirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 14, 'E os apóstolos que estavam em Jerusalém, ao ouvirem que Samaria tinha recebido a palavra de Deus, enviaram-lhes a Pedro e a João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 15, 'Os quais, tendo descido, oraram por eles, para que recebessem ao Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 16, '(Porque ainda sobre nenhum deles tinha descido; mas somente tinham sido batizados no nome do Senhor Jesus).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 17, 'Então puseram as mãos sobre eles, e receberam o Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 18, 'E Simão ao ver que pela imposição das mãos dos apóstolos se dava o Espírito Santo, ofereceu-lhes dinheiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 19, 'Dizendo: Dai também a mim este poder, que sobre qualquer um em quem eu puser as mãos, receba o Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 20, 'Mas Pedro lhe disse: Teu dinheiro seja contigo para perdição, porque pensaste que o dom de Deus [pudesse] ser obtido por meio de dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 21, 'Tu não tens parte nem porção nesta palavra; porque teu coração não é correto diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 22, 'Arrepende-te, pois, desta tua maldade, e ora a Deus, para que talvez este pensamento de teu coração te seja perdoado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 23, 'Porque eu vejo que tu estás em fel amargo, e atado em injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 24, 'Mas respondendo Simão, disse: Orai vós por mim ao Senhor, para que nada do que dissestes venha sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 25, 'Tendo eles pois dado testemunho e falado a palavra do Senhor, voltaram a Jerusalém, e em muitas aldeias dos samaritanos anunciaram o Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 26, 'E um anjo do Senhor falou a Filipe, dizendo: Levanta-te, e vai para o sul, ao caminho que desce de Jerusalém para Gaza, que é deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 27, 'E ele levantou-se, e foi, e eis que um homem etíope, eunuco, administrador [subordinado] a Candace, a rainha dos etíopes, que estava sobre [o controle] de todos os bens dela, tinha vindo a Jerusalém para adorar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 28, 'E ele estava voltando, sentado em sua carruagem, [e] lia ao profeta Isaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 29, 'E o Espírito disse a Filipe: Aproxima-te, e ajunta-te a esta carruagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 30, 'E Filipe, correndo, ouviu que ele estava lendo ao profeta Isaías, e disse: Tu entendes o que estás lendo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 31, 'E ele disse: Como eu poderia, se alguém não me ensinar? E pediu a Filipe que subisse e se sentasse com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 32, 'E o lugar da Escritura que ele estava lendo era este: Como ovelha ele foi levado ao matadouro, e como um cordeiro mudo fica diante do que o tosquia, assim [também] ele não abriu sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 33, 'Em sua humilhação foi tirado seu julgamento; e quem anunciará sua geração? Porque da terra sua vida é tirada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 34, 'E respondendo o eunuco a Filipe, disse: Eu te rogo, de quem o profeta diz isto? De si mesmo, ou de alguém outro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 35, 'E Filipe, abrindo sua boca, e começando desta escritura, anunciou-lhe o Evangelho [de] Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 36, 'E enquanto eles iam caminhando, chegaram a uma certa [porção] de água; e o eunuco disse: Eis aqui água; o que me impede de ser batizado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 37, 'E Filipe disse: Se tu crês de todo coração, [então] é lícito;E respondendo ele, disse: Creio que Jesus Cristo é o Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 38, 'E ele mandou parar a carruagem; e desceram ambos à água, tanto Filipe como o eunuco; e ele o batizou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 39, 'E quando eles subiram da água, o Espírito do Senhor arrebatou a Filipe, e o eunuco não mais o viu, porque ele foi [em] seu caminho com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 8, 40, 'Mas Filipe se achou em Azoto; e passando, anunciava ao Evangelho [em] todas as cidades, até que veio a Cesareia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 1, 'E Saulo, ainda assoprando ameaças e mortes contra os discípulos do Senhor, foi ao chefe dos sacerdotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 2, 'E pediu-lhe cartas para Damasco, para as sinagogas, para que se achasse alguns deste caminho, tanto homens como mulheres, ele [os] trouxesse presos a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 3, 'E indo, aconteceu que chegando perto de Damasco, repentinamente brilhou ao redor dele uma luz do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 4, 'E caindo em terra, ouviu ma voz lhe dizendo: Saulo, Saulo, por que me persegues?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 5, 'E ele disse: Quem és, Senhor?E o Senhor disse: Eu sou Jesus, a quem tu persegues; duro é para ti dar coices contra os aguilhões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 6, 'E ele, tremendo e atônito, disse: Senhor, que queres que eu faça?E o Senhor lhe [disse] : Levanta-te, e entra na cidade; e [ali] te será dito o que deves fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 7, 'E os homens que viajavam com ele pararam emudecidos, ouvindo, de fato, a voz, porém não vendo ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 8, 'E Saulo se levantou da terra e, tendo aberto seus olhos, não via ninguém; e sendo guiado pela mão, levaram-no a Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 9, 'E ele estava três dias sem ver; e não comeu, nem bebeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 10, 'E havia em Damasco um certo discípulo, de nome Ananias; e disse-lhe o Senhor em visão: Ananias!E ele respondeu: Eis-me aqui, Senhor!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 11, 'E o Senhor lhe [disse] : Levanta-te, e vai a rua chamada Direita, e pergunta na casa de Judas por um chamado Saulo, de Tarso; porque que ele ora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 12, 'E ele viu em visão que um homem, de nome Ananias, entrava, e sobre ele punha a mão, para que voltasse a ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 13, 'E Ananias respondeu: Senhor, eu ouvi de muitos sobre este homem, quantos males ele tem feito aos teus santos em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 14, 'E aqui ele tem poder dos chefes dos sacerdotes para prender a todos os que invocam o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 15, 'Mas o Senhor lhe disse: Vai, porque este me é um vaso escolhido para levar meu nome diante dos gentios, e dos reis, e dos filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 16, 'Porque eu mostrarei a ele o quanto ele deve sofrer por causa do meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 17, 'E Ananias foi, e entrou na casa; e pondo as mãos sobre ele, disse: Irmão Saulo, o Senhor, [que é] Jesus, aquele que apareceu a ti no caminho, me enviou para que tu voltes a ver, e sejas cheio do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 18, 'E logo lhe caíram como que escamas dos olhos, e imediatamente voltou a ver; e levantando-se, foi batizado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 19, 'E ao comer, ele se fortaleceu. E Saulo ficou alguns dias com os discípulos [que estavam] em Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 20, 'E logo nas sinagogas pregava a Cristo, [dizendo] que aquele era o Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 21, 'E todos os que o ouviam ficavam admirados, e diziam: Não é este aquele que em Jerusalém tentava destruir aos que invocavam este nome? E [não foi] para isso [que] ele veio aqui, para os levar presos aos chefes dos sacerdotes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 22, 'Mas Saulo se esforçava muito mais, e confundia aos judeus que habitavam em Damasco, provando que aquele era o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 23, 'E passados vários dias, os judeus tiveram conselho entre si para o matarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 24, 'Mas as ciladas deles foram conhecidas por Saulo; e eles vigiavam as portas, tanto de dia como de noite, para poderem matá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 25, 'Porém os discípulos, tomando-o de noite, levaram-no abaixo pelo muro em um cesto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 26, 'E Saulo, tendo vindo a Jerusalém, procurava se juntar aos discípulos; mas todos tinham medo dele, não crendo que fosse discípulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 27, 'Mas Barnabás, tomando-o consigo, trouxe [-o] aos apóstolos, e contou-lhes como no caminho tinha visto ao Senhor, e tinha lhe falado, e como em Damasco tinha falado ousadamente no nome de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 28, 'E ele estava junto deles, entrando e saindo em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 29, 'E falando ousadamente no nome do Senhor Jesus; falava e discutia também contra os gregos; mas eles procuravam matá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 30, 'E os irmãos, ao perceberem [isto] , o levaram até Cesareia, e o enviaram a Tarso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 31, 'Então as igrejas por toda a Judeia, e Galileia, e Samaria, tinham paz, e eram edificadas; e andando no temor do Senhor, e [na] consolação do Espírito Santo, se multiplicavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 32, 'E aconteceu que, Pedro, passando por todos [os lugares] , veio também aos santos que habitavam em Lida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 33, 'E ali ele achou a um certo homem chamado Enéas, que havia oito anos que jazia numa cama, que era paralítico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 34, 'E Pedro lhe disse: Enéas, Jesus Cristo te cura; levanta-te, e faz tua cama. E logo ele se levantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 35, 'E todos os que habitavam em Lida e Sarona o viram, os quais se converteram ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 36, 'E havia em Jope uma certa discípula, de nome Tabita, que traduzido se diz Dorcas. Esta estava cheia de boas obras e doações que ela fazia [aos necessitados] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 37, 'E aconteceu naqueles dias, que tendo ela ficado doente, morreu; e tendo a lavado, puseram-na no compartimento superior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 38, 'E como Lida era perto de Jope, os discípulos, ao ouvirem que Pedro estava ali, mandaram-lhe dois homens, rogando [-lhe] que não demorasse a vir a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 39, 'E Pedro, tendo se levantado, foi com eles; o qual chegou, e [o] levaram ao compartimento superior, e todas as viúvas o rodearam, chorando, e mostrando [-lhe] as túnicas e roupas que Dorcas tinha feito quando estava com elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 40, 'Mas Pedro, pondo para fora a todas; pôs-se de joelhos, e orou; e virando-se para o corpo, disse: Tabita, levanta-te;E ela abriu seus olhos, e vendo a Pedro, sentou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 41, 'E ele, dando-lhe a mão, levantou-a; e tendo chamado aos santos, e às viúvas, apresentou-a viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 42, 'E isto ficou conhecido por toda Jope, e muitos creram no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 9, 43, 'E aconteceu que ele ficou muitos dias em Jope, com um certo Simão curtidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 1, 'E havia um certo homem em Cesareia, de nome Cornélio, centurião, do esquadrão chamado Italiano;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 2, 'Devoto, e temente a Deus, com toda a sua casa; e que fazia muitas doações ao povo, e continuamente orava a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 3, 'Ele viu claramente em visão, cerca da hora nona do dia, a um anjo de Deus, que vinha a ele, e lhe dizia: Cornélio!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 4, 'E ele, olhando-lhe atentamente, e muito atemorizado, disse: O que é, Senhor?E disse-lhe: Tuas orações e doações subiram à memória diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 5, 'E agora envia homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 6, 'Este está hospedado na casa de um Simão curtidor, cuja casa é junto ao mar; este te dirá o que deves fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 7, 'E tendo partido o anjo que falava com Cornélio, ele chamou a dois de seus servos, e a um soldado devoto, dos que permaneciam continuamente com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 8, 'E tendo lhes contado tudo, enviou-os a Jope.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 9, 'E no dia seguinte, enquanto estes iam pelo caminho, e chegando perto da cidade, Pedro subiu ao telhado para orar, quase à hora sexta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 10, 'E tendo ele fome, quis comer; [e] enquanto estavam [lhe] preparando, caiu sobre ele um êxtase.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 11, 'E ele viu o céu aberto, e descia a ele um certo objeto, como um grande lençol, amarrado pelas quatro pontas, e abaixando-se à terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 12, 'Em que havia de todos os animais quadrúpedes da terra, e animais selvagens, e répteis, e aves do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 13, 'E veio-lhe uma voz, [dizendo] : Pedro, mata e come.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 14, 'Mas Pedro disse: De maneira nenhuma, Senhor; porque nunca comi coisa alguma ordinária ou impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 15, 'E a voz voltou a [dizer] ,pela segunda vez: O que Deus purificou, não faças tu [como se fosse] ordinário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 16, 'E isto aconteceu três vezes; e o objeto voltou a ser recolhido acima ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 17, 'E enquanto Pedro estava pensando perplexo consigo mesmo o que seria aquela visão que ele tinha visto, eis que os homens que tinham sido enviados por Cornélio, perguntando pela casa de Simão, pararam à porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 18, 'E chamando, perguntaram se Simão, que tinha por sobrenome Pedro, estava hospedado ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 19, 'E estando Pedro pensando naquela visão, o Espírito lhe disse: Eis que três homens te buscam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 20, 'Então levanta-te, desce, e vai com eles, sem duvidar; porque eu os enviei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 21, 'E Pedro, tendo descido aos homens que tinham lhe sido enviados por Cornélio, disse: Eis que eu sou a quem buscais; qual é o motivo pelo qual estais aqui?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 22, 'E eles disseram: Cornélio, [que é] centurião, homem justo e temente a Deus, [e] que tem [bom] testemunho de toda a nação dos judeus, foi revelado por um santo anjo para te chamar até a casa dele, e ouvir de tuas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 23, 'Então chamando-os para dentro, recebeu-os em casa. Mas no dia seguinte, Pedro foi com eles; e foram com ele alguns dos irmãos de Jope.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 24, 'E no dia seguinte chegaram a Cesareia. E Cornélio estava esperando por eles, tendo chamado a seus parentes e amigos mais íntimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 25, 'E sucedeu que, ao Pedro entrar, Cornélio se encontrou com ele, e caindo aos pés dele, adorou-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 26, 'Mas Pedro o levantou, dizendo: Levanta-te; eu mesmo também sou um ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 27, 'E tendo conversado com ele, entrou; e achou a muitos que [ali] tinham se reunido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 28, 'E disse-lhes: Vós sabeis como não é lícito a um homem judeu juntar-se de estrangeiros, ou aproximar-se deles; mas Deus me mostrou que a ninguém chame de ordinário ou impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 29, 'Portanto eu, tendo sido chamado, vim sem qualquer oposição [de minha parte] . Então eu pergunto: por que motivo me mandastes chamar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 30, 'E Cornélio disse: Há quatro dias que, até esta hora eu estava jejuando, e orava à hora nona em minha casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 31, 'E eis que um homem se pôs diante de mim com uma roupa brilhante, e disse: Cornélio, tura oração tem sido ouvida, e tuas doações têm sido lembradas diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 32, 'Envia pois a Jope, e manda chamar a Simão, que tem por sobrenome Pedro; este se hospeda na casa de Simão o curtidor, junto ao mar; quando ele vier, falará contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 33, 'Então logo eu enviei a ti; e bem fizeste em vir até aqui; agora pois estamos todos [aqui] presentes diante de Deus, para ouvir tudo quanto Deus tem te ordenado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 34, 'E Pedro, abrindo a boca, disse: Reconheço que é verdade que Deus não faz acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 35, 'Mas sim, em toda nação, aquele que o teme, e pratica a justiça, [este] lhe é agradável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 36, 'A palavra que Deus enviou aos filhos de Israel, anunciando o Evangelho da paz por meio de Jesus Cristo; este é o Senhor de todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 37, 'Vós sabeis da palavra que veio por toda a Judeia, começando desde a Galileia, depois do batismo que João pregou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 38, '[E] sobre Jesus de Nazaré; como Deus o ungiu com o Espírito Santo, e com poder; o qual percorreu [os lugares] fazendo o bem, e curando a todos os oprimidos pelo diabo; porque Deus era com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 39, 'E nós somos testemunhas de todas as coisas que ele fez; tanto na terra dos judeus, como em Jerusalém; ao qual mataram, pendurando [-o] em um madeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 40, 'A este Deus ressuscitou ao terceiro dia, e fez com que fosse manifesto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 41, 'Não a todo o povo, mas sim a testemunhas determinadas por Deus com antecedência: a nós, que juntamente com ele comemos e bebemos, depois dele ter ressuscitado dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 42, 'E ele nos mandou pregar ao povo, e dar testemunho de que ele é o que foi ordenado por Deus [para ser] Juiz dos vivos e dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 43, 'A este todos os profetas dão testemunho, de que todos os que nele crerem receberão perdão dos pecados por meio do seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 44, 'E estando Pedro ainda falando estas palavras, o Espírito Santo caiu sobre todos os que ouviam a palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 45, 'E os crentes que eram da circuncisão, tantos quantos tinham vindo com Pedro, ficaram muito admirados de que também sobre os gentios fosse derramado o dom do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 46, 'Porque eles os ouviam falar em [diversas] línguas, e a engrandecer a Deus. Então Pedro respondeu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 47, 'Por acaso pode alguém impedir a água, para que não sejam batizados estes, que também, assim como nós, receberam o Espírito Santo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 10, 48, 'E mandou que fossem batizados no nome do Senhor. Então lhe pediram que continuasse [com eles] por alguns dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 1, 'E os apóstolos, e os irmãos que estavam na Judeia, ouviram que também os gentios receberam a palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 2, 'E quando Pedro subiu a Jerusalém, discutiam contra ele os que eram da circuncisão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 3, 'Dizendo: Tu entraste [na casa] de homens incircuncisos, e comeste com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 4, 'Mas Pedro começou a lhes explicar [tudo] em ordem, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 5, 'Eu estava orando na cidade de Jope, e vi em êxtase uma visão: um certo objeto que descia como um grande lençol, pelas quatro pontas abaixado desde o céu, e vinha até mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 6, 'No qual, olhando eu com atenção, considerei e vi quatro quadrúpedes da terra, e animais selvagens, e répteis, e aves do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 7, 'E eu ouvi uma voz que me dizia: Levanta-te Pedro, mata e come.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 8, 'Mas eu disse: De maneira nenhuma, Senhor; porque nunca comi coisa alguma ordinária, nem coisa imunda entrou em minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 9, 'E a voz me respondeu do céu pela segunda vez: O que Deus purificou, não o faças tu [como] ordinário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 10, 'E isto aconteceu por três vezes; e voltou-se tudo a recolher acima ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 11, 'E eis que logo três homens, enviados a mim de Cesareia, pararam junto à casa onde eu estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 12, 'E o Espírito me disse que eu fosse com eles, sem duvidar; e também estes seis irmãos foram comigo, e entramos na casa daquele homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 13, 'E ele nos contou como tinha visto um anjo estar em sua casa, e tinha lhe dito: Envia [alguns] homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 14, 'O qual te falará palavras, em que tu sejas salvo, e [também] toda a tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 15, 'E quando comecei a falar, caiu o Espírito Santo sobre eles, assim como também no princípio [tinha caído] sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 16, 'E eu me lembrei da palavra do Senhor, como ele tinha dito: Verdadeiramente João batizou com água, mas vós sereis batizados com o Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 17, 'Portanto, se Deus deu a eles igual dom, assim como também a nós, que temos crido no Senhor Jesus Cristo; quem era eu, pois, para que pudesse proibir a Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 18, 'E ao ouvirem estas coisas, se acalmaram, e glorificavam a Deus, dizendo: Portanto também aos gentios Deus deu arrependimento para a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 19, 'E os que foram dispersos por causa da perseguição que aconteceu por causa de Estêvão, passaram até a Fenícia, e Chipre, e Antioquia; não falando a ninguém a palavra, a não ser somente aos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 20, 'E havia deles alguns homens cipriotas e cirenenses, os quais ao entrarem em Antioquia, falaram aos gregos, anunciando o Evangelho do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 21, 'E a mão do Senhor era com eles, e um grande número creu, e se converteu ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 22, 'E esta notícia sobre eles chegou aos ouvidos da igreja que estava em Jerusalém; e enviaram a Barnabé, para ir até Antioquia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 23, 'O qual, ao chegar [lá] ,e tendo visto a graça de Deus, alegrou-se; e exortou a todos, para que com o propósito do coração permanecessem no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 24, 'Porque ele era um bom homem, e cheio do Espírito Santo, e de fé; e uma grande multidão foi acrescentada ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 25, 'E Barnabé foi para Tarso, para buscar a Saulo; e achando-o, trouxe-o a Antioquia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 26, 'E sucedeu que, [durante] um ano completo eles se congregaram naquela igreja, e ensinavam a uma grande multidão; e em Antioquia os discípulos foram chamados pela primeira vez de cristãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 27, 'E naqueles dias desceram de Jerusalém [alguns] profetas a Antioquia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 28, 'E levantando-se um deles, por nome Ágabo, declarou pelo Espírito, que estava para haver uma grande fome em todo o mundo; que veio a acontecer no tempo de Cláudio César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 29, 'E os discípulos determinaram de cada um, conforme o que pudesse, mandar algum [socorro] para serviço dos irmãos que habitavam na Judeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 11, 30, 'O que também fizeram, enviando [-o] aos anciãos pela mão de Barnabé e de Saulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 1, 'E por aquele mesmo tempo o rei Herodes pôs as mãos para maltratar a alguns da igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 2, 'E matou a Tiago, o irmão de João, pela espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 3, 'E vendo que isto agradava aos judeus, ele fez ainda mais, para também prender a Pedro (e eram os dias dos [pães] sem fermento).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 4, 'Do qual, também detendo, lançou-o na prisão, entregando [-o] a quatro quaternos de soldados, que o guardassem; pretendendo tirá-lo [para mostrá-lo] ao povo depois da Páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 5, 'Então Pedro era mantido na prisão; mas a igreja fazia fervorosa oração a Deus por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 6, 'E quando Herodes estava para tirá-lo [para apresentá-lo] ,naquela mesma noite Pedro estava dormindo entre dois soldados, acorrentado com duas correntes; e os guardas diante da porta guardavam a prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 7, 'E eis que veio acima um anjo do Senhor, e uma luz brilhou na prisão; e tocando em Pedro em sua lateral, despertou-o, dizendo; Levanta-te, depressa!E as correntes caíram de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 8, 'E o anjo lhe disse: Arruma-te, e amarra as tuas sandálias.E ele fez assim. E disse-lhe: Põe tua capa sobre ti, e segue-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 9, 'E saindo, o seguia; e não sabia que era verdade o que se fazia pelo anjo, mas pensava que estava tendo alguma visão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 10, 'E ao passarem a primeira e a segunda guarda, chegaram à porta de ferro, que leva à cidade, a qual foi aberta por si mesma; e tendo saído, foram a uma rua, e logo o anjo partiu dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 11, 'E tendo Pedro voltado a si, disse: Agora eu sei verdadeiramente que o Senhor enviou a seu anjo, e me livrou da mão de Herodes, e de toda a expectativa do povo dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 12, 'E ele, reconhecendo [isto] ,foi à casa de Maria, a mãe de João, que tinha por sobrenome Marcos, onde muitos estavam juntos, e oravam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 13, 'E Pedro, tendo batido a porta da entrada,veio uma moça de nome Rode, para escutar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 14, 'E ela, reconhecendo a voz de Pedro, de alegria não abriu a porta da entrada, em vez disso ela correu para dentro, e anunciou que Pedro estava fora à porta da entrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 15, 'E lhe disseram: Tu estás delirando.Mas ela, insistindo que assim era. E eles diziam: É o anjo dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 16, 'Mas Pedro continuava a bater; e ao abrirem, viram-no, e ficaram espantados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 17, 'Mas ele, fazendo-lhes gestos para que calassem, contou-lhes como o Senhor tinha lhe tirado da prisão, e disse: Anunciai isto a Tiago e aos irmãos.E tendo saído, foi para outro lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 18, 'E vindo o dia, havia não pouca perturbação entre os soldados, sobre o que, pois, tinha acontecido com Pedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 19, 'E quando Herodes o buscou, e não o achou, tendo investigado aos guardas, mandou que eles fossem levados [para serem mortos] . E partindo da Judeia para Cesareia, ficou [ali] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 20, 'E Herodes estava extremamente irritado com os de Tiro e de Sidom; porém eles, vindo em concordância até ele, e persuadindo a Blasto, que era o camareiro do rei, pediram paz, porque a terra deles dependia dos alimentos da terra do rei [Herodes] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 21, 'E num dia marcado, Herodes vestiu roupas reais, e sentando no tribunal, fez-lhes um discurso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 22, 'E o povo exclamava: Voz de deus, e não de homem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 23, 'E no mesmo instante um anjo do Senhor o feriu, porque ele não deu a glória a Deus; e tendo sido comido por vermes, deixou de respirar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 24, 'E a palavra de Deus crescia, e se multiplicava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 12, 25, 'E Barnabé e Saulo, tendo cumprido aquele serviço, voltaram a Jerusalém, tomando também consigo a João, o que tinha por sobrenome Marcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 1, 'E havia em Antioquia, na igreja que estava [ali] , alguns profetas e mestres: Barnabé e Simeão, chamado Níger, e Lúcio cireneu, e Manaem, que tinha sido criado na infância junto com Herodes o Tetrarca, e Saulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 2, 'E tendo eles prestado serviço ao Senhor, e jejuado, o Espirito Santo disse: Separai-me a Barnabé e a Saulo, para a obra para a qual eu os tenho chamado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 3, 'Então jejuando, e orando, e pondo as mãos sobre eles, [os] despediram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 4, 'Portanto estes, enviados pelo Espírito Santo, desceram a Selêucia, e dali navegaram para o Chipre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 5, 'E tendo chegado a Salamina, anunciavam a palavra de Deus nas sinagogas dos judeus; e também tinham a João como trabalhador [para os auxiliar] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 6, 'E tendo eles atravessado a Ilha até Pafo, acharam a um certo mago, falso profeta, judeu, cujo nome era Barjesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 7, 'O qual estava com o procônsul Sérgio Paulo, homem prudente. Este, tendo chamado a si a Barnabé, e a Saulo, procurava muito ouvir a palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 8, 'Mas resistia-lhes Elimas, o mago (que assim significa seu nome), procurando afastar o procônsul da fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 9, 'Mas Saulo, que também [se chama] Paulo, cheio do Espírito Santo, e olhando fixamente para ele, disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 10, 'Ó filho do diabo, cheio de toda enganação e toda malícia, inimigo de toda justiça, não cessarás de perverter os corretos caminhos do Senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 11, 'E agora, eis que a mão do Senhor [está] contra ti, e serás cego, não vendo o sol por algum tempo.E no mesmo instante caiu sobre ele um embaçamento, e trevas; e ele, andando ao redor, procurava alguém que o guiasse pela mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 12, 'Então o procônsul, vendo o que tinha acontecido, creu, espantado pela doutrina do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 13, 'E tendo partido de Pafo, Paulo e os que estavam com ele foram a Perges, [cidade] da Panfília. Mas João, separando-se deles, voltou a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 14, 'E eles, tendo passado de Perges, vieram a Antioquia, [cidade] da Pisídia; e ao entrarem na sinagoga [n] um dia de sábado, sentaram-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 15, 'E depois da leitura da Lei e dos profetas, os chefes da sinagoga lhes mandaram, dizendo: Homens irmãos, se em vós há [alguma] palavra de exortação ao povo, dizei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 16, 'E Paulo, levantando-se e fazendo gesto com a mão, disse: Homens israelitas, e [vós] os que temeis a Deus, ouvi:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 17, 'O Deus deste povo de Israel escolheu a nossos pais, e exaltou ao povo, sendo eles estrangeiros na terra do Egito, e com o braço levantando, ele os tirou dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 18, 'E pelo tempo de cerca de quarenta anos, ele suportou os costumes deles no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 19, 'E tendo destruído a sete nações na terra de Canaã, repartiu-lhes as terras por sorte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 20, 'E depois disto, cerca de quatrocentos e cinquenta anos, ele [lhes] deu juízes, até o profeta Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 21, 'E depois disto, pediram a um Rei, e ele lhes deu a Saul, filho de Quis, homem da tribo de Benjamim, [durante] quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 22, 'E tirando a este, levantou-lhes por rei a Davi, ao qual também deu testemunho, e disse: Eu achei a Davi, [filho] de Jessé, um homem conforme o meu coração, que fará toda a minha vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 23, 'Da descendência deste, conforme a promessa, Deus levantou a Jesus por Salvador de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 24, 'Tendo João primeiro, antes de sua vinda, pregado o batismo de arrependimento a todo o povo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 25, 'Mas quando João cumpriu [sua] carreira, disse: Quem vós pensais que eu sou? Eu não sou o [Cristo] ,mas eis que após mim vem aquele, cujas sandálias dos pés eu não sou digno de desatar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 26, 'Homens irmãos, filhos da descendência de Abraão, e os que dentre vós temem a Deus, a vós é enviada a palavra desta salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 27, 'Porque os que habitavam em Jerusalém, e seus líderes, não conhecendo a este, ao condenarem [-no] ,cumpriram as vozes dos profetas, que são lidas todos os sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 28, 'E [mesmo] achando nenhum motivo para morte, pediram a Pilatos que fosse morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 29, 'E tendo eles cumprido todas as coisas que estavam escritas sobre ele, tirando [-o] do madeiro, puseram [-no] na sepultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 30, 'Mas Deus o ressuscitou dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 31, 'O qual foi visto durante muitos dias pelos que haviam subido com ele da Galileia, que são suas testemunhas para com o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 32, 'E nós vos anunciamos o Evangelho da promessa que foi feita aos pais; ao qual Deus já nos cumpriu a nós, filhos deles, ressuscitando a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 33, 'Assim como está escrito no salmo segundo: Tu és meu Filho, hoje eu te gerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 34, 'E [quanto a] que o ressuscitasse dos mortos, para nunca mais voltar à degradação, assim disse: Eu vos darei as fiéis beneficências de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 35, 'Por isso que também em outro [salmo] ele diz: Não permitirás que teu Santo veja degradação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 36, 'Porque, na verdade, tendo Davi servido ao conselho de Deus, morreu, foi posto junto a seus pais, e viu degradação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 37, 'Mas aquele a quem Deus ressuscitou nenhuma degradação viu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 38, 'Seja-vos pois conhecido, homens irmãos, que por este vos é anunciado o perdão dos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 39, 'E de tudo o que pela lei de Moisés não pudestes ser justificados, neste é justificado todo aquele que crê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 40, 'Então vede, para que não venha sobre vós o que está escrito nos [livros dos] profetas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 41, '[Vós] desprezadores, vede e espantai-vos, e desaparecei-vos; porque eu opero obra em vossos dias, obra na qual não crereis, se alguém vos contar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 42, 'E tendo os judeus saído da sinagoga,os gentios rogaram [-lhes] que no sábado seguinte eles lhes falassem estas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 43, 'E tendo terminado [a reunião] da sinagoga, muitos dos judeus, e dos religiosos prosélitos, seguiram a Paulo e a Barnabé; os quais, falando-lhes, exortavam-nos a permanecerem na graça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 44, 'E no sábado seguinte ajuntou-se quase toda a cidade para ouvir a palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 45, 'Mas os Judeus, ao verem as multidões, ficaram cheios de inveja, e falavam contrariamente ao que Paulo dizia, falando contrariamente e blasfemando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 46, 'Mas Paulo e Barnabé, usando de ousadia, disseram: Era necessário que a palavra de Deus fosse primeiro falada a vós; mas já que a rejeitais, e não vos julgais dignos da vida eterna, eis que nós nos viramos [em direção] aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 47, 'Porque assim o Senhor nos mandou, [dizendo] : Eu te pus como luz para os gentios, para que tu sejas como salvação até às extremidades da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 48, 'E os gentios, tendo ouvido [isto] ,alegraram-se, e glorificavam ao Senhor; e creram todos quantos estavam determinados para a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 49, 'E a palavra do Senhor era divulgada por toda aquela região.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 50, 'Mas os judeus incitaram algumas mulheres devotas e honradas, e aos líderes da cidade, e levantaram perseguição contra Paulo e Barnabé, e os expulsaram de seus limites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 51, 'Mas eles, sacudindo contra eles o pó dos seus pés, vieram a Icônio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 13, 52, 'E os discípulos se enchiam de alegria e do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 1, 'E aconteceu em Icônio, que entraram juntos na sinagoga dos judeus, e falaram de tal maneira que creu uma grande multidão, tanto de judeus como de gregos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 2, 'Mas os judeus incrédulos incitaram e irritaram os ânimos dos gentios contra os irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 3, 'Então eles ficaram [ali] por muito tempo, falando ousadamente no Senhor, o qual dava testemunho à palavra de sua graça, concedendo [que] sinais e milagres fossem feitos pelas mãos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 4, 'E a multidão da cidade se dividiu; e uns eram a favor dos judeus, e outros a favor dos apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 5, 'E fazendo-se uma rebelião, tanto de judeus como de gentios, juntos com seus líderes, para falarem mal deles, e os apedrejarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 6, 'E eles, sabendo [disto] ,fugiram para as cidades da Licaônia, [chamadas] Listra e Derbe; e à região ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 7, 'E ali eles anunciavam ao Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 8, 'E um certo homem em Listra estava sentado, tendo incapacidade nos pés, aleijado desde o ventre de sua mãe, que nunca tinha andado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 9, 'Este ouviu Paulo falando; o qual, olhando com atenção, e vendo que ele tinha fé para ser curado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 10, 'Disse em alta voz: Levanta-te direito sobre teus pés.E ele saltou e andou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 11, 'E as multidões, vendo o que Paulo tinha feito, levantaram suas vozes, dizendo em [língua] licaônica: Os deuses se fizeram semelhantes a homens, e desceram até nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 12, 'E chamaram a Barnabé de Júpiter; e a Paulo, de Mercúrio; porque este era o líder ao falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 13, 'E o sacerdote de Júpiter, que estava diante da cidade deles, trazendo touros e grinaldas à entrada da porta, ele, junto com as companhias, queria oferecer sacrifício [a eles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 14, 'Mas os apóstolos Barnabé e Paulo, ao ouvirem [isto] ,rasgaram suas roupas, e saltaram entre a multidão, clamando,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 15, 'E dizendo: Homens, por que fazeis estais coisas? Também nós somos homens como vós, sujeitos às mesmas emoções; e vos anunciamos o Evangelho para que vos convertais destas vaidades para o Deus vivo, que fez o céu, a terra, o mar, e tudo quanto neles há.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 16, 'O qual nas gerações passadas deixou os os gentios andarem seus [próprios] caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 17, 'Ainda que, contudo, não tenha deixado a si mesmo sem testemunho, fazendo o bem desde o céu, dando-nos chuvas, e tempos frutíferos, [e] enchendo nossos corações de alimento e alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 18, 'E tendo disto isto, apenas detiveram as multidões de que não fizessem sacrifícios a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 19, 'Mas vieram [alguns] judeus de Antioquia, e de Icônio, e persuadiram a multidão; e apedrejando a Paulo, arrastaram [-no] para fora da cidade, pensando que ele estivesse morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 20, 'Mas, tendo os discípulos ficado ao seu redor, ele se levantou, e entrou na cidade; e no dia seguinte saiu com Barnabé para Derbe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 21, 'E tendo anunciado o Evangelho àquela cidade, e feito muitos discípulos, eles voltaram a Listra, e a Icônio, e a Antioquia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 22, 'Confirmando os ânimos dos discípulos, e exortando-os para que permanecessem na fé, e que nos é necessário entrar no Reino de Deus por meio de muitas aflições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 23, 'E tendo escolhido por votação anciãos para cada igreja, orando com jejuns, eles foram enviados ao Senhor, no qual tinham crido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 24, 'E tendo passado por Pisídia, vieram à Panfília.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 25, 'E tendo falado a palavra em Perges, desceram a Atália.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 26, 'E dali navegaram para Antioquia, onde tinham sido encomendados à graça de Deus para a obra que eles [já] tinham cumprido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 27, 'E ao chegarem, e reunirem a igreja, relataram quão grandes coisas Deus tinha feito com eles; e como ele tinha aberto a porta da fé aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 14, 28, 'E eles ficaram ali não pouco tempo com os discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 1, 'E alguns que tinham descido da Judeia ensinavam aos irmãos, [dizendo] : Se vós não vos circuncidardes conforme o costume de Moisés, não podeis ser salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 2, 'Então, havendo não pequena resistência e confronto de Paulo e Barnabé contra eles, ordenaram que Paulo, Barnabé e alguns outros deles subissem aos apóstolos e aos anciãos a Jerusalém sobre esta questão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 3, 'Então sendo eles preparados para a viagem e despedidos pela igreja, passaram pela Fenícia e Samaria, contando [sobre] a conversão dos gentios; e davam grande alegria a todos os irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 4, 'E tendo chegado a Jerusalém, eles foram recebidos pela igreja, e pelos apóstolos e anciãos; e lhes anunciaram quão grandes coisas Deus tinha feito com eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 5, 'Mas [que] alguns do grupo dos fariseus que tinham crido, levantaram-se, dizendo que era necessário circuncidá-los, e mandar [-lhes] que guardem a Lei de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 6, 'E os apóstolos e anciãos se reuniram para dar atenção a este assunto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 7, 'E havendo muita discussão, Pedro se levantou, e lhes disse: Homens irmãos, vós sabeis que há muito tempo Deus [meu] escolheu entre nós, para que por minha boca os gentios ouvissem a palavra do Evangelho, e cressem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 8, 'E Deus, que conhece os corações, deu-lhes testemunho, dando-lhes o Espírito Santo, assim como também a nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 9, 'E nenhuma diferença fez entre nós e eles, purificando seus corações pela fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 10, 'Então agora, por que tentais a Deus, pondo um jugo sobre o pescoço dos discípulos; que nem nossos pais, nem nós podemos levar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 11, 'Mas cremos que, pela graça do Senhor Jesus Cristo, nós somos salvos, assim como também eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 12, 'E toda a multidão se calou; e ouviram a Barnabé e a Paulo, que contavam quão grandes sinais e milagres Deus tinha feito por meio deles entre os gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 13, 'E tendo estes se calado, Tiago respondeu, dizendo: Homens irmãos, ouvi-me:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 14, 'Simão informou como primeiro Deus visitou aos gentios, para tomar [deles] um povo para seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 15, 'E com isso concordam as palavras dos profetas, como está escrito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 16, 'Depois disto eu voltarei, e reconstruirei o tabernáculo de Davi, que caído está; e reconstruirei [de] suas ruínas, e voltarei a levantá-lo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 17, 'Para que o resto da humanidade busque ao Senhor, e todos os gentios sobre os quais meu nome é invocado, diz o Senhor, que faz todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 18, 'São conhecidas por Deus desde a antiguidade todas as suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 19, 'Portanto eu julgo que aqueles que dos gentios se convertem a Deus não devem ser perturbados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 20, 'Mas [que] lhes escrevamos para que se abstenham das contaminações dos ídolos, e do pecado sexual, e da [carne] sufocada, e do sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 21, 'Porque Moisés, desde as gerações antigas, tem em cada cidade quem o pregue nas sinagogas, sendo lido todo sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 22, 'Então pareceu bem aos apóstolos, e aos anciãos, com toda a igreja, eleger deles [alguns] homens, para serem enviados com Paulo e Barnabé a Antioquia: Judas, que tinha por sobrenome Barsabás; e a Silas, homens líderes entre os irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 23, 'E escreveram por meio deles o seguinte: Os apóstolos e os anciãos, e os irmãos – para os irmãos dentre os gentios, que [estão] em Antioquia, Síria e Cilícia; saudações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 24, 'Dado que ouvimos que alguns dos que saíram de nós vos perturbaram com palavras, [e] causaram incômodo a vossas almas, dizendo que deveis vos circuncidar e guardar a Lei, aos quais não mandamos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 25, 'Pareceu-nos bem, reunidos em concordância, escolher [alguns] homens, e enviá-los até vós, com nossos amados Barnabé e Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 26, 'Homens que têm arriscado suas vidas pelo nome de nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 27, 'Então enviamos a Judas e a Silas, os quais [vos] dirão as mesmas coisas pessoalmente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 28, 'Porque pareceu bem ao Espírito Santo e a nós, de nenhuma carga a mais vos impor, a não ser estas coisas necessárias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 29, 'Que vos abstenhais das coisas sacrificadas aos ídolos, do sangue, da [carne] sufocada, e do pecado sexual; das quais, se vos guardardes, fareis bem. Que o bem vos suceda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 30, 'Sendo, pois, eles despedidos, vieram a Antioquia, e reunindo a multidão, entregaram a carta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 31, 'E ao lerem, alegraram-se pela consolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 32, 'E então Judas e Silas, sendo também profetas, com muitas palavras exortaram e firmaram aos irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 33, 'E ficando [ali] por algum tempo, permitiram que voltassem em paz dos irmãos para os apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 34, 'Mas a Silas pareceu bem continuar ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 35, 'E Paulo e Barnabé ficaram em Antioquia, ensinando e evangelizando, com também muitos outros, a palavra do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 36, 'E depois de alguns dias, Paulo disse a Barnabé: Voltemos a visitar a nossos irmãos em cada cidade onde tenhamos anunciado a palavra do Senhor, [para ver] como estão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 37, 'E Barnabé aconselhou para que tomassem consigo a João, chamado Marcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 38, 'Mas Paulo achou adequado que não tomassem consigo a aquele que desde a Panfília tinha se separado deles, e não tinha ido com eles para [aquela] obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 39, 'Houve então [entre eles] tal discórdia, que eles se separaram um do outro; e Barnabé, tomando consigo a Marcos, navegou para o Chipre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 40, 'Mas Paulo, escolhendo a Silas, partiu-se, enviado pelos irmãos para a graça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 15, 41, 'E ele passou pela Síria e Cilícia, firmando as igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 1, 'E ele veio a Derbe e Listra; e eis que estava ali um certo discípulo, de nome Timóteo, filho de uma certa mulher judia crente, mas de pai grego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 2, 'Do qual era [bem] testemunhado pelos irmãos [que estavam] em Listra e Icônio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 3, 'A este Paulo quis que fosse com ele; e tomando-o, circuncidou-o, por causa dos judeus, que estavam naqueles lugares; porque todos conheciam o pai dele, que era grego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 4, 'E eles, passando pelas cidades, entregavam-lhes as ordenanças que foram determinadas pelos apóstolos e anciãos em Jerusalém, para que [as] guardassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 5, 'E assim as Igrejas eram firmadas na fé, e cada dia aumentavam em número.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 6, 'E passando pela Frígia, e pela região da Galácia, foi-lhes impedido pelo Espírito Santo de falarem a palavra na Ásia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 7, '[E] quando eles vieram a Mísia, tentaram ir à Bitínia; mas o Espírito não lhes permitiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 8, 'E tendo passado por Mísia, desceram a Trôade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 9, 'E uma visão foi vista por Paulo durante a noite: um homem Macedônio se pôs [diante dele] ,rogando-lhe, e dizendo: Passa à Macedônia, e ajuda-nos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 10, 'E quando ele viu a visão, logo procuramos partir para a Macedônia, concluindo que o Senhor estava nos chamando para anunciarmos o Evangelho a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 11, 'Então, tendo navegado desde Trôade, viemos correndo caminho direto a Samotrácia, e no [dia] seguinte a Neápolis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 12, 'E dali a Filipos, que é a primeira cidade desta parte da Macedônia, [e é] uma colônia; e estivemos naquela cidade [por] alguns dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 13, 'E no dia de sábado saímos para fora da cidade, onde costumava ser feita oração; e tendo [nos] sentado, falamos às mulheres que tinham se ajuntado [ali] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 14, 'E uma certa mulher, por nome Lídia, vendedora de púrpura, da cidade de Tiatira, que servia a Deus; [ela nos] ouviu; o coração da qual o Senhor abriu, para que prestasse atenção ao que Paulo dizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 15, 'E quando ela foi batizada, e [também] sua casa, ela [nos] rogou, dizendo: Se vós tendes julgado que eu seja fiel ao Senhor, entrai em minha casa e ficai ali.E ela insistiu para conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 16, 'E aconteceu, que ao estarmos nós indo à oração, saiu ao nosso encontro uma moça que tinha espírito de pitonisa; a qual ao fazer adivinhações trazia grande lucro a seus senhores.')
